package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StringEscapeUtils.escapeJava(Writer out, String str)
 */
public class StringEscapeUtils_escapeJava_TriageGen1Test {







    @Test
    public void testEscapeJava_SpecialCharacters() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "quote: \", backslash: \\, tab: \t, newline: \n, carriage return: \r");
        // Expected: quote: \", backslash: \\, tab: \t, newline: \n, carriage return: \r
        // Note: The actual escape output for a literal tab is \t
        assertEquals("quote: \\\", backslash: \\\\, tab: \\t, newline: \\n, carriage return: \\r", out.toString());
    }






}

package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.exception.NestableRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StringEscapeUtils.escapeJava(Writer out, String str)
 */
public class StringEscapeUtils_escapeJava_TriageGen1Test {









    @Test
    public void testEscapeJava_UnicodeCharacters() throws IOException {
        StringWriter out = new StringWriter();
        StringEscapeUtils.escapeJava(out, "unicode: \u0000, \u001F, \u007F, \u00A9");
        // \u0000 -> \u0000
        // \u001F -> \u001f
        // \u007F -> \u007f
        // \u00A9 -> \u00a9
        assertEquals("unicode: \\u0000, \\u001f, \\u007f, \\u00a9", out.toString());
    }




}

